begin;
select plan(7);
select is((select count(*)::integer from public.hb_policy_versions where status='active' and ((reviewed_by='partial-official-fields-2026-10-15' and version=2) or (reviewed_by='icp-renewal-common-conditions-2026-10-22' and version=3))),11,'Eleven reviewed services retain active policy coverage after the scoped successor');
select is((select count(*)::integer from public.hb_service_bindings where metadata->>'recorded_detail_review' in ('partial-official-fields-2026-10-15','icp-renewal-common-conditions-2026-10-22') and (metadata->>'source_scope_unresolved')::boolean),4,'Four partially scoped services retain unresolved category eligibility');
select is(
 (select count(*)::integer from public.hb_policy_versions p cross join lateral jsonb_array_elements(p.rules) r where p.reviewed_by='partial-official-fields-2026-10-15' and p.status='active' and r->>'id'='conditions' and r->>'reason'='غير موثق بعد')
 +(select count(*)::integer from public.hb_policy_versions p join public.hb_service_bindings b on b.policy_key=p.policy_key and b.jurisdiction_id is not distinct from p.jurisdiction_id where p.reviewed_by='icp-renewal-common-conditions-2026-10-22' and p.status='active' and b.metadata->>'eligibility_scope'='common-only' and b.metadata->>'category_specific_eligibility_verified'='false'),4,'Three unknown eligibility records plus one explicitly common-only record remain partial');
select is((select count(*)::integer from public.hb_policy_versions p cross join lateral jsonb_array_elements(p.rules) r where p.reviewed_by='partial-official-fields-2026-10-15' and p.status='active' and r->>'id'='official-steps'),7,'Seven source-reviewed official procedures are available');
select ok(not exists(select 1 from public.hb_service_bindings b join public.hb_workflow_templates w on w.workflow_key=b.workflow_key and w.status='active' cross join lateral jsonb_array_elements(w.definition->'steps') s where b.metadata->>'recorded_detail_review' in ('partial-official-fields-2026-10-15','icp-renewal-common-conditions-2026-10-22') and s->>'taskType'='external' and coalesce((s->>'requiresApproval')::boolean,false)=false),'External execution still requires approval, including the scoped successor');
select ok(exists(select 1 from public.hb_policy_versions p join public.hb_policy_versions old on old.policy_key=p.policy_key and old.jurisdiction_id is not distinct from p.jurisdiction_id and old.version=2 where p.status='active' and p.reviewed_by='icp-renewal-common-conditions-2026-10-22' and p.source_ids=old.source_ids and (select jsonb_agg(x order by x->>'id') from jsonb_array_elements(p.rules) x where x->>'id'<>'conditions')=(select jsonb_agg(x order by x->>'id') from jsonb_array_elements(old.rules) x where x->>'id'<>'conditions')),'Common-only review preserves source identity and every unrelated policy rule');
select ok(exists(select 1 from public.hb_service_bindings b join public.hb_policy_versions p on p.policy_key=b.policy_key and p.jurisdiction_id is not distinct from b.jurisdiction_id cross join lateral jsonb_array_elements(p.rules) r where b.service_slug='تجديد-تصريح-إقامة-عبر-icp-خارج-دبي' and b.active and p.status='active' and b.metadata->>'source_scope_unresolved'='true' and b.metadata->>'category_specific_eligibility_verified'='false' and r->>'id'='conditions' and r->>'reason'=$fact$الشروط العامة الموثقة: صلاحية جواز السفر لا تقل عن 6 أشهر، واستمرار استيفاء متطلبات إصدار الإقامة عند التجديد. لا تثبت هذه الشروط العامة أهلية فئة بعينها؛ اختر الفئة في بطاقة ICP وطابق متطلباتها قبل التقديم.$fact$),'Recorded common conditions never claim category eligibility');
select * from finish();rollback;
